const clock = new THREE.Clock();
scene.background = new THREE.Color(0xf4f7fb);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const keyLight = new THREE.DirectionalLight(0xfff8e7, 1.4);
keyLight.position.set(6, 10, 8);
keyLight.castShadow = true;
keyLight.shadow.mapSize.width = 2048;
keyLight.shadow.mapSize.height = 2048;
keyLight.shadow.bias = -0.0001;

const fillLight = new THREE.DirectionalLight(0xd6e3ff, 0.6);
fillLight.position.set(-7, 4, 5);

const rimLight = new THREE.PointLight(0x88ccff, 0.5, 25);
rimLight.position.set(-4, 3, -5);

const quantumLight = new THREE.PointLight(0x00ffff, 0.8, 15);
quantumLight.position.set(0, 2, 0);

scene.add(new THREE.AmbientLight(0x7f8aa6, 0.35), keyLight, fillLight, rimLight, quantumLight);

const floorGeometry = new THREE.CircleGeometry(15, 128);
const floorMaterial = new THREE.MeshStandardMaterial({ 
  color: 0xe8eef5, 
  roughness: 0.9, 
  metalness: 0.05 
});
const floor = new THREE.Mesh(floorGeometry, floorMaterial);
floor.rotation.x = -Math.PI / 2;
floor.position.y = -3;
floor.receiveShadow = true;
scene.add(floor);

const gridHelper = new THREE.GridHelper(30, 30, 0xcfd9e8, 0xe1e8f0);
gridHelper.position.y = -2.99;
scene.add(gridHelper);

const birdGroup = new THREE.Group();
scene.add(birdGroup);

const bodyGeo = new THREE.CapsuleGeometry(0.4, 1.2, 8, 16);
const bodyMat = new THREE.MeshPhysicalMaterial({
  color: 0x4a5568,
  roughness: 0.6,
  metalness: 0.1,
  iridescence: 0.3,
  iridescenceIOR: 1.3
});
const body = new THREE.Mesh(bodyGeo, bodyMat);
body.rotation.z = Math.PI / 2;
body.rotation.y = Math.PI / 2;
body.castShadow = true;
birdGroup.add(body);

const headGeo = new THREE.SphereGeometry(0.32, 32, 32);
const head = new THREE.Mesh(headGeo, bodyMat);
head.position.set(0.9, 0.2, 0);
birdGroup.add(head);

const beakGeo = new THREE.ConeGeometry(0.08, 0.3, 16);
const beakMat = new THREE.MeshStandardMaterial({ color: 0xffa500, roughness: 0.4 });
const beak = new THREE.Mesh(beakGeo, beakMat);
beak.rotation.z = -Math.PI / 2;
beak.position.set(1.15, 0.15, 0);
birdGroup.add(beak);

const leftWingGroup = new THREE.Group();
leftWingGroup.position.set(0.2, 0.1, 0.35);
birdGroup.add(leftWingGroup);

const innerWingGeo = new THREE.BoxGeometry(0.8, 0.1, 0.4);
const wingMat = new THREE.MeshPhysicalMaterial({
  color: 0x5a6c7d,
  roughness: 0.7,
  metalness: 0.1,
  transmission: 0.1
});
const leftInnerWing = new THREE.Mesh(innerWingGeo, wingMat);
leftInnerWing.position.set(0.4, 0, 0);
leftInnerWing.castShadow = true;
leftWingGroup.add(leftInnerWing);

const leftOuterWingGroup = new THREE.Group();
leftOuterWingGroup.position.set(0.8, 0, 0);
leftWingGroup.add(leftOuterWingGroup);

const outerWingGeo = new THREE.BoxGeometry(0.9, 0.05, 0.25);
const leftOuterWing = new THREE.Mesh(outerWingGeo, wingMat);
leftOuterWing.position.set(0.45, 0, 0);
leftOuterWing.castShadow = true;
leftOuterWingGroup.add(leftOuterWing);

for(let i = 0; i < 5; i++) {
  const featherGeo = new THREE.ConeGeometry(0.02, 0.3, 8);
  const feather = new THREE.Mesh(featherGeo, wingMat);
  feather.rotation.z = -Math.PI / 2 + (i * 0.1);
  feather.position.set(0.9 + (i * 0.08), 0, -0.1 + (i * 0.05));
  leftOuterWingGroup.add(feather);
}

const rightWingGroup = leftWingGroup.clone();
rightWingGroup.position.set(0.2, 0.1, -0.35);
rightWingGroup.scale.z = -1;
birdGroup.add(rightWingGroup);

const tailGeo = new THREE.BoxGeometry(0.6, 0.05, 0.5);
const tail = new THREE.Mesh(tailGeo, wingMat);
tail.position.set(-0.7, -0.1, 0);
birdGroup.add(tail);

const quantumGroup = new THREE.Group();
birdGroup.add(quantumGroup);

const cloudGeo = new THREE.IcosahedronGeometry(1.5, 3);
const cloudMat = new THREE.MeshBasicMaterial({
  color: 0x00ffff,
  wireframe: true,
  transparent: true,
  opacity: 0.15
});
const probabilityCloud = new THREE.Mesh(cloudGeo, cloudMat);
quantumGroup.add(probabilityCloud);

const cloudGeo2 = new THREE.IcosahedronGeometry(1.2, 2);
const cloudMat2 = new THREE.MeshBasicMaterial({
  color: 0xff00ff,
  wireframe: true,
  transparent: true,
  opacity: 0.1
});
const probabilityCloud2 = new THREE.Mesh(cloudGeo2, cloudMat2);
quantumGroup.add(probabilityCloud2);

const particleCount = 200;
const particleGeo = new THREE.BufferGeometry();
const positions = new Float32Array(particleCount * 3);
const velocities = [];

for(let i = 0; i < particleCount; i++) {
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.acos(2 * Math.random() - 1);
  const r = 1.5 + Math.random() * 2;

  positions[i * 3] = r * Math.sin(phi) * Math.cos(theta);
  positions[i * 3 + 1] = r * Math.sin(phi) * Math.sin(theta);
  positions[i * 3 + 2] = r * Math.cos(phi);

  velocities.push({
    x: (Math.random() - 0.5) * 0.02,
    y: (Math.random() - 0.5) * 0.02,
    z: (Math.random() - 0.5) * 0.02,
    phase: Math.random() * Math.PI * 2
  });
}

particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
const particleMat = new THREE.PointsMaterial({
  color: 0x00aaff,
  size: 0.05,
  transparent: true,
  opacity: 0.6,
  blending: THREE.AdditiveBlending
});
const quantumParticles = new THREE.Points(particleGeo, particleMat);
quantumGroup.add(quantumParticles);

const ringGroup = new THREE.Group();
quantumGroup.add(ringGroup);

const rings = [];
for(let i = 0; i < 3; i++) {
  const ringGeo = new THREE.TorusGeometry(2 + i * 0.5, 0.02, 16, 100);
  const ringMat = new THREE.MeshBasicMaterial({
    color: 0x00ffff,
    transparent: true,
    opacity: 0.3 - (i * 0.08)
  });
  const ring = new THREE.Mesh(ringGeo, ringMat);
  ring.rotation.x = Math.PI / 2;
  ringGroup.add(ring);
  rings.push({ mesh: ring, speed: 0.5 + i * 0.2, offset: i * 2 });
}

const flowLines = [];
const flowCount = 20;

for(let i = 0; i < flowCount; i++) {
  const points = [];
  for(let j = 0; j < 10; j++) {
    points.push(new THREE.Vector3(-3 - j * 0.5, (Math.random() - 0.5) * 0.5, (Math.random() - 0.5) * 2));
  }
  const curve = new THREE.CatmullRomCurve3(points);
  const tubeGeo = new THREE.TubeGeometry(curve, 20, 0.01, 8, false);
  const tubeMat = new THREE.MeshBasicMaterial({
    color: 0xffffff,
    transparent: true,
    opacity: 0.2
  });
  const tube = new THREE.Mesh(tubeGeo, tubeMat);
  tube.userData = { speed: 2 + Math.random(), offset: Math.random() * 10 };
  scene.add(tube);
  flowLines.push(tube);
}

camera.position.set(5, 3, 6);
camera.lookAt(0, 0, 0);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.maxPolarAngle = Math.PI / 2 - 0.1;

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  const flapSpeed = 8;
  const flapAmp = 0.4;

  leftWingGroup.rotation.z = Math.sin(t * flapSpeed) * flapAmp;
  rightWingGroup.rotation.z = Math.sin(t * flapSpeed) * flapAmp;

  const leftOuterWingGroup = leftWingGroup.children[1];
  const rightOuterWingGroup = rightWingGroup.children[1];
  leftOuterWingGroup.rotation.z = Math.sin(t * flapSpeed - 0.5) * (flapAmp * 0.8) + 0.2;
  rightOuterWingGroup.rotation.z = Math.sin(t * flapSpeed - 0.5) * (flapAmp * 0.8) + 0.2;

  birdGroup.position.y = Math.sin(t * flapSpeed * 2) * 0.05 + Math.sin(t * 0.5) * 0.5;
  birdGroup.rotation.z = Math.sin(t * 0.3) * 0.05;

  gridHelper.position.z = (t * 2) % 2;

  probabilityCloud.rotation.x = t * 0.2;
  probabilityCloud.rotation.y = t * 0.3;
  probabilityCloud.scale.setScalar(1 + Math.sin(t * 0.5) * 0.1);

  probabilityCloud2.rotation.x = -t * 0.25;
  probabilityCloud2.rotation.z = t * 0.15;

  const posArray = quantumParticles.geometry.attributes.position.array;
  for(let i = 0; i < particleCount; i++) {
    const vel = velocities[i];
    const idx = i * 3;

    posArray[idx] += Math.sin(t * 0.5 + vel.phase) * 0.01 + vel.x;
    posArray[idx + 1] += Math.cos(t * 0.3 + vel.phase) * 0.01 + vel.y;
    posArray[idx + 2] += Math.sin(t * 0.4 + vel.phase) * 0.01 + vel.z;

    const dist = Math.sqrt(posArray[idx]**2 + posArray[idx+1]**2 + posArray[idx+2]**2);
    if(dist > 4) {
      posArray[idx] *= 0.5;
      posArray[idx+1] *= 0.5;
      posArray[idx+2] *= 0.5;
    }
  }
  quantumParticles.geometry.attributes.position.needsUpdate = true;
  quantumParticles.rotation.y = t * 0.1;

  rings.forEach((ring, i) => {
    const scale = 1 + Math.sin(t * ring.speed + ring.offset) * 0.2;
    ring.mesh.scale.set(scale, scale, scale);
    ring.mesh.rotation.x = Math.PI / 2 + Math.sin(t * 0.5 + i) * 0.1;
    ring.mesh.material.opacity = (0.3 - i * 0.08) * (0.5 + Math.sin(t * 2 + i) * 0.5);
  });

  flowLines.forEach(line => {
    line.position.x += line.userData.speed * 0.01;
    if(line.position.x > 3) {
      line.position.x = -5;
      line.material.opacity = 0.2;
    }
    const dist = Math.abs(line.position.x - birdGroup.position.x);
    if(dist < 1.5) {
      line.material.opacity = 0.4 * (1 - dist/1.5);
    }
  });

  quantumLight.intensity = 0.6 + Math.sin(t * 3) * 0.2;
  rimLight.intensity = 0.45 + Math.sin(t * 1.2) * 0.1;

  controls.update();
  renderer.render(scene, camera);
}

animate();

